"""Write docs/REPORT_bio_nodes.md from the generated data."""
import json, glob, os, sys
from collections import Counter, defaultdict
sys.path.insert(0, os.path.dirname(__file__))
from lib import ROOT
from presets import SPEC
nodes = []
for f in sorted(glob.glob(ROOT + '/data/nodes/bio_*.json')): nodes += json.load(open(f))
by = {n['id']: n for n in nodes}
tr = json.load(open(ROOT + '/data/tracks/biology.json'))
st = json.load(open(os.path.join(os.path.dirname(__file__), 'validate_out.json')))['stats']
files = sorted(os.path.basename(f) for f in glob.glob(ROOT + '/data/nodes/bio_*.json'))
L = []
w = L.append
w('# Biology (B.S.) content graph: report\n')
w('Generated by `tools/bio_nodes/run_all.sh` (generators `g_*.py` -> `finalize.py` -> `validate.py` -> `report.py`). Validation passes with 0 errors. Nothing existing was edited and nothing was committed.\n')
w('## Files written\n')
w('- `data/nodes/` (%d files): %s' % (len(files), ', '.join('`%s`' % f for f in files)))
w('- `data/tracks/biology.json` (%d sections)' % len(tr['sections']))
w('- `tools/bio_nodes/` (`lib.py`, `g_1_foundations.py` ... `g_10_extra.py`, `finalize.py`, `validate.py`, `presets.py`, `report.py`, `run_all.sh`)')
w('- **To wire in:** add the 14 `bio_*.json` names to `data/nodes/manifest.json` and `"biology.json"` to `data/tracks/manifest.json`.\n')
w('## Counts\n')
w('- **%d new nodes** (21 area hubs + root `biology_degree` + %d content nodes), %d prerequisite (`needs`) edges, acyclic across new and reused nodes, track order respects `needs`.' % (st['total_new'], st['total_new'] - 22, st['edges_needs']))
w('- Track: %d entries, of which **%d are reused existing nodes** (human body systems/organs/tissues/cells/organelles, 16 physiology processes, EE math nodes) and the rest new. %d distinct reused ids are also linked from new nodes via `needs`/`related`/`parents`.' % (st['track_total'], st['reused_in_track'], st['reused_ids_referenced']))
w('- Templates: %s; kinds: %s' % (st['templates'], st['kinds']))
w('- Certainty: %s. Every C2/C3 node has `open_questions`.' % st['certainty'])
w('- With OpenStax `refs`: %d; with `ext`: %d (Wikipedia/NCBI/UniProt/PDB only, stable titles); with neither: %d' % (st['with_refs'], st['with_ext'], st['no_refs_no_ext']))
w('- With `where`: %d; with `lab`: %d; with `formula`: %d; with `kn`: %d; with `molecules`: %d\n' % (st['with_where'], st['with_lab'], st['with_formula'], st['with_kn'], st['with_molecules']))
w('## Nodes per track section\n')
w('| Section | New nodes | Track entries (incl. reused) |\n|---|---|---|')
for s in tr['sections']:
    w('| %s | %d | %d |' % (s['title'], st['per_section_new'][s['title']], st['per_section_track'][s['title']]))
w('\n## Kinds per section\n')
w('| Section | ' + ' | '.join(sorted(st['kinds'])) + ' |\n|---|' + '---|' * len(st['kinds']))
for s in tr['sections']:
    c = Counter(by[i]['kind'] for i in s['nodes'] if i in by)
    w('| %s | %s |' % (s['title'], ' | '.join(str(c.get(k, 0)) for k in sorted(st['kinds']))))
w('\n## Schema notes\n')
w('Same fields as `ee_*.json` and `body_*.json`: `id, title, kind, template, scale_m, area, parents, parts, made_of, processes, related, mesh, needs, summary, layers{basics,deeper,expert}, facts, formula, did_you_know, certainty, open_questions, refs, ext, kn, molecules, where, lab, steps`.')
w('- `parents` = the section hub (`bio_*`) and every hub has parent root `biology_degree`; `parts` is the auto-filled inverse of `parents` among new nodes. Existing nodes were not edited, so reused nodes do not list new children in `parts`.')
w('- `needs` = prerequisites (new nodes may need reused ones such as `limits_continuity`, `ode_first_order`, `random_variables`). `related` is used for soft links, including links to the 16 existing physiology processes (`cellular_respiration`, `protein_synthesis`, `mitosis`...), which are listed in the Processes section.')
w('- `where` is one of the allowed place ids (`place:cell`, `place:dna`, `place:leaf`...), `mol:<id>` for molecules, or an existing body node id (`neuron`, `heart`, `retina`, `nephron`, `brain`...). Nodes with no sensible physical home (statistics, lab methods) have no `where`.')
w('- Process nodes: template `process`, 6 steps each, `focus` ids validated against nodes, `mol:` ids or places.')
w('- `translation_process` was **not** created: the existing `protein_synthesis` (human-body process) is reused, and `bio_translation_steps` and `bio_trna_translation_machinery` add the details.\n')
w('## Process nodes (19 new + 16 reused)\n')
for n in nodes:
    if n['template'] == 'process': w('- `%s` (%d steps): %s' % (n['id'], len(n['steps']), n['title']))
w('- Reused: cellular_respiration, protein_synthesis (covers translation), mitosis, action_potential, synaptic_transmission, muscle_contraction, cardiac_cycle, breathing, digestion, urine_formation, blood_clotting, immune_response, hormone_signaling, thermoregulation, vision, bone_remodeling.\n')
w('## Open questions (C2-C4)\n')
for n in nodes:
    if n['certainty'] != 'C1': w('- `%s` (%s): %s' % (n['id'], n['certainty'], n['open_questions'][0]))
w('\n## Gaps and caveats\n')
nr = [n['id'] for n in nodes if not n['refs'] and not n.get('ext') and n['kind'] != 'field']
w('- Nodes with no OpenStax ref or ext link (%d, mostly lab/skills/statistics ones where OpenStax has no matching section): %s' % (len(nr), ', '.join('`%s`' % i for i in nr)))
w('- Prose is original and compact (2 short sentences per layer); numeric facts are rounded or approximate (marked ≈) and should get an expert review pass, especially figures for recent counts (species numbers, case counts, costs).')
w('- `ext` links are intentionally sparse: Wikipedia articles (stable titles), NCBI BLAST, UniProt, PubMed, RCSB PDB entries (1UBQ, 4HHB, 1EMA, 1BNA). They were not fetched or checked live (no network check), so run a URL checker before shipping. 1CRN (crambin) and the crystal ids were not used.')
w('- Not covered in depth: biochemistry of vitamins/minerals beyond cofactors, detailed organic synthesis, histology of specific organs beyond reused body nodes, parasitology life-cycle atlas, bioimage analysis, bioacoustics, forensic entomology, ethnobotany, evolutionary psychology, quantum biology. Zoology/entomology are covered at basics level (`bio_entomology_insects`, `bio_zoology_taxonomy_methods`).')
w('- Reused body nodes are placed in the animal physiology, neuroscience, immunology and processes sections; their own `parents` still point to the body systems, so the world view and the track show two different hierarchies for them.')
w('- `where` assigns no place for proteins (1UBQ/1CRN/1BNA/4HHB/1EMA are only linked as `ext`); a `protein:<pdb>` where-type would let the 3D world host them. `molecules` ids not in `molecules_all.json` (e.g. plain `glucose`; use `glucose_alpha`/`glucose_beta`) were avoided.\n')
w('## Planned lab presets (to build)\n')
w('%d presets across the six labs (`genetics`, `population`, `microscope`, `molecule`, `enzyme`, `ecosystem`); none exist yet.\n' % len(SPEC))
used = defaultdict(list)
for n in nodes:
    if 'lab' in n: used[(n['lab']['id'], n['lab']['preset'])].append(n['id'])
w('| Lab:preset | Used by | Spec |\n|---|---|---|')
for k in sorted(used): w('| `%s:%s` | %s | %s |' % (k[0], k[1], ', '.join(used[k]), SPEC[k]))
open(ROOT + '/docs/REPORT_bio_nodes.md', 'w').write('\n'.join(L) + '\n')
print('report written', len(L), 'lines')
